     1	#!/usr/bin/env bun
     2	/**
     3	 * dispatch_ci.ts — start the repository's check workflow against a branch.
     4	 *
     5	 * A pull request opened with `GITHUB_TOKEN` fires no `pull_request` event, so the
     6	 * checks it requires never start on their own. This is the same hole
     7	 * `adapters/actions/dispatch-targets.ts` states once — GitHub starts no workflow
     8	 * run for an event its own token triggered — and the bridge there (`dispatchCi`)
     9	 * is what closes it for an agent's pull request. This script is the thin shell
    10	 * between a workflow's step and that bridge, the way `dispatch_update.ts` is for
    11	 * `!upgrade`: the arguments come from the caller, the decision is the bridge's.
    12	 *
    13	 * Usage:
    14	 *   dispatch_ci.ts --repo OWNER/REPO --branch BRANCH
    15	 */
    16	import { parseArgs } from "node:util";
    17	import { dispatchCi } from "../../adapters/actions/dispatch-targets.ts";
    18	import { defineScript } from "./lib/script-ref.ts";
    19	
    20	export interface DispatchCiArgs {
    21	  /** `owner/name` of the repository — this one. */
    22	  repo: string;
    23	  /** The branch whose head the checks should run against. */
    24	  branch: string;
    25	}
    26	
    27	export const ref = defineScript<DispatchCiArgs>(import.meta.url);
    28	
    29	function main(): void {
    30	  const { values } = parseArgs({
    31	    args: Bun.argv.slice(2),
    32	    options: {
    33	      repo: { type: "string" },
    34	      branch: { type: "string" },
    35	    },
    36	  });
    37	
    38	  const repo = (values.repo ?? process.env.GITHUB_REPOSITORY ?? "").trim();
    39	  const branch = (values.branch ?? "").trim();
    40	  if (!repo || !branch) {
    41	    console.error("usage: dispatch_ci.ts --repo OWNER/REPO --branch BRANCH  (or set GITHUB_REPOSITORY)");
    42	    process.exit(2);
    43	  }
    44	
    45	  const sent = dispatchCi(branch);
    46	  if (!sent) {
    47	    console.error(
    48	      `::error::could not dispatch the check workflow against ${branch}. Nothing was started — ` +
    49	        "check the workflow name, then re-run this step.",
    50	    );
    51	    process.exit(1);
    52	  }
    53	  console.error(`[dispatch-ci] the check workflow was started against ${branch}`);
    54	}
    55	
